// ═══════════════════════════════════════════════════════════════════
// DESIGN SYSTEM — tokens centralizados
// ═══════════════════════════════════════════════════════════════════
const DS = {
  // Spacing scale
  sp: { xs:4, sm:8, md:12, lg:16, xl:20, "2xl":24, "3xl":32, "4xl":48 },
  // Border radius scale
  r: { sm:6, md:8, lg:10, xl:14, "2xl":16, full:9999 },
  // Typography scale
  font: { xs:10, sm:11, md:12, base:13, lg:14, xl:16, "2xl":20, "3xl":26, "4xl":34 },
  // Font weights
  w: { regular:400, medium:500, semibold:600, bold:700, black:800 },
  // Shadows
  shadow: {
    sm: "0 1px 2px rgba(0,0,0,0.04)",
    md: "0 2px 8px rgba(0,0,0,0.08)",
    lg: "0 8px 24px rgba(0,0,0,0.12)",
    xl: "0 16px 48px rgba(0,0,0,0.18)",
  },
  // Easing
  ease: "cubic-bezier(0.4, 0, 0.2, 1)",
};

// ─── Componentes base reusables ───────────────────────────────────────
function Card({T, children, hoverable, onClick, style={}, padding="lg"}) {
  const [hover, setHover] = React.useState(false);
  const padMap = {sm:"10px 12px", md:"14px 16px", lg:"18px 20px", xl:"24px 28px"};
  return (
    <div onClick={onClick}
      onMouseEnter={()=>hoverable&&setHover(true)}
      onMouseLeave={()=>setHover(false)}
      style={{
        background: T.card,
        border: `1px solid ${hover&&hoverable?T.accentSolid+"55":T.border}`,
        borderRadius: DS.r.xl,
        padding: padMap[padding]||padMap.lg,
        transition: `all 0.15s ${DS.ease}`,
        cursor: onClick?"pointer":"default",
        ...style,
      }}>
      {children}
    </div>
  );
}

function Skeleton({T, width="72%", height=22, radius=6, style={}}) {
  return <div style={{width,height,borderRadius:radius,background:T?T.surface:"#1e1e2e",position:"relative",overflow:"hidden",...style}}><div style={{position:"absolute",inset:0,background:"linear-gradient(90deg,transparent 0%,rgba(255,255,255,0.07) 50%,transparent 100%)",backgroundSize:"200% 100%",animation:"skeleton 1.4s ease infinite"}}/></div>;
}

function KPI({T, label, value, sub, color, icon, accent, onClick, compact, loading}) {
  const c = color||T.accentSolid;
  return (
    <Card T={T} hoverable={!!onClick} onClick={onClick} padding={compact?"md":"lg"} style={{borderColor:accent?c+"55":T.border}}>
      <div style={{display:"flex",alignItems:"flex-start",gap:DS.sp.md}}>
        {icon&&<div style={{fontSize:compact?16:18,flexShrink:0,opacity:loading?0.3:0.9}}>{icon}</div>}
        <div style={{flex:1,minWidth:0}}>
          <div style={{fontSize:DS.font.xs,textTransform:"uppercase",color:T.textSm,fontWeight:DS.w.semibold,letterSpacing:0.5,marginBottom:5}}>{label}</div>
          {loading
            ? <Skeleton T={T} height={compact?18:24} width="65%" style={{marginBottom:6}}/>
            : <div style={{fontSize:compact?DS.font["2xl"]:DS.font["3xl"],fontWeight:DS.w.black,color:c,letterSpacing:-0.6,lineHeight:1}}>{value}</div>
          }
          {loading
            ? <Skeleton T={T} height={11} width="45%" style={{marginTop:6}}/>
            : sub&&<div style={{fontSize:DS.font.xs,color:T.textSm,marginTop:4}}>{sub}</div>
          }
        </div>
      </div>
    </Card>
  );
}

// Sistema de botones unificado — visualmente idéntico a BtnPrimary/BtnSecondary/BtnDanger
function Btn({T, variant="primary", size="md", icon, children, onClick, disabled, style={}, ...rest}) {
  const variants = {
    // Igual a BtnPrimary(T): gradiente violeta→índigo
    primary:   {bg:"linear-gradient(135deg, #6d28d9, #4338ca)", color:"#fff", border:"transparent", shadow:"0 2px 12px #6d28d933"},
    // Igual a BtnSecondary(T): transparente con borde
    secondary: {bg:"transparent", color:T.textMd, border:T.border, shadow:"none"},
    // Ghost: sin relleno ni borde
    ghost:     {bg:"transparent", color:T.textMd, border:"transparent", shadow:"none"},
    // Igual a BtnDanger(T): fondo rojo suave, texto rojo
    danger:    {bg:T.redBg, color:T.red, border:T.red+"44", shadow:"none"},
    // Success: verde sólido
    success:   {bg:T.green, color:"#fff", border:"transparent", shadow:`0 2px 8px ${T.green}33`},
  };
  const sizes = {
    sm: {padding:"5px 10px", fontSize:DS.font.sm, gap:5},
    md: {padding:"8px 14px", fontSize:DS.font.base, gap:6},
    lg: {padding:"10px 20px", fontSize:DS.font.lg, gap:8},
  };
  const v = variants[variant]||variants.primary;
  const s = sizes[size]||sizes.md;
  return (
    <button onClick={onClick} disabled={disabled} {...rest}
      style={{
        background: disabled?T.surface:v.bg,
        color: disabled?T.textSm:v.color,
        border: `1px solid ${v.border==="transparent"?"transparent":v.border}`,
        borderRadius: DS.r.md,
        cursor: disabled?"not-allowed":"pointer",
        fontWeight: DS.w.semibold,
        fontFamily: "'Inter',system-ui,sans-serif",
        letterSpacing:"0.01em",
        display:"inline-flex",alignItems:"center",justifyContent:"center",
        transition: `all 0.15s ${DS.ease}`,
        opacity: disabled?0.5:1,
        boxShadow: disabled?"none":v.shadow,
        ...s,
        ...style,
      }}>
      {icon&&<span style={{display:"inline-flex",alignItems:"center"}}>{icon}</span>}
      {children}
    </button>
  );
}

function DSEmpty({T, icon="📭", title, subtitle, action}) {
  return (
    <Card T={T} padding="xl" style={{textAlign:"center"}}>
      <div style={{fontSize:42,marginBottom:DS.sp.md,opacity:0.8}}>{icon}</div>
      <div style={{fontSize:DS.font.lg,fontWeight:DS.w.bold,color:T.text,marginBottom:DS.sp.xs}}>{title}</div>
      {subtitle&&<div style={{fontSize:DS.font.md,color:T.textSm,marginBottom:action?DS.sp.lg:0,maxWidth:400,margin:"0 auto"}}>{subtitle}</div>}
      {action&&<div style={{marginTop:DS.sp.lg}}>{action}</div>}
    </Card>
  );
}

// ─── Org Switcher (multi-org F1+F2) ───
// Chip estilo "workspace switcher" estilo Shopify/Linear:
// - Pill abajo del sidebar con avatar del user + icono+nombre de la org activa + ▾
// - Popover arriba muestra: card de la org activa (con Gestionar), lista de otras
//   orgs o empty state "No hay otras organizaciones", botón "+ Crear organización"
// - Plan gate: free/starter/pro → máx 2 orgs; total → ilimitado
function OrgSwitcher({T, user, userPlan, orgs, activeOrgId, onSwitchOrg, onOpenCreateOrg, onOpenManageOrg, collapsed}) {
  const [open, setOpen] = React.useState(false);
  const [dropPos, setDropPos] = React.useState({top:0,left:0,width:260});
  const btnRef = React.useRef(null);
  const dropRef = React.useRef(null);

  React.useEffect(()=>{
    if (!open) return;
    // Compute position from button
    if (btnRef.current) {
      const r = btnRef.current.getBoundingClientRect();
      setDropPos({top: r.top - 6, left: r.left, width: Math.max(260, r.width)});
    }
    const onClick = (e) => {
      if (btnRef.current?.contains(e.target)) return;
      if (dropRef.current?.contains(e.target)) return;
      setOpen(false);
    };
    const onEsc = (e) => { if (e.key === "Escape") setOpen(false); };
    document.addEventListener("mousedown", onClick);
    document.addEventListener("keydown", onEsc);
    return () => {
      document.removeEventListener("mousedown", onClick);
      document.removeEventListener("keydown", onEsc);
    };
  },[open]);

  if (!Array.isArray(orgs) || orgs.length === 0) return null;
  const active = orgs.find(o => o.id === activeOrgId) || orgs[0];
  const others = orgs.filter(o => o.id !== active.id);
  const planAllowsMore = userPlan === "total" || orgs.length < 2;
  const initialOf = (name) => (name||"?").trim().charAt(0).toUpperCase() || "?";
  const userInitial = (user?.displayName||user?.email||"?").trim().charAt(0).toUpperCase();

  // Avatar de la org: cuadrado redondeado con la inicial sobre color de la org
  const OrgAvatar = ({org, size=22}) => (
    <span style={{width:size,height:size,borderRadius:Math.max(4, size/4.5),background:org.color||T.accent,color:"#fff",display:"flex",alignItems:"center",justifyContent:"center",fontWeight:DS.w.bold,fontSize:Math.round(size*0.5),flexShrink:0,letterSpacing:0.3,boxShadow:"inset 0 -1px 0 rgba(0,0,0,0.15)"}}>
      {initialOf(org.name)}
    </span>
  );

  return (
    <div style={{padding:`${DS.sp.xs}px ${DS.sp.sm}px 0`}}>
      <button
        ref={btnRef}
        onClick={()=>setOpen(o=>!o)}
        title={collapsed?`Organización: ${active.name}`:undefined}
        style={{
          width:"100%",display:"flex",alignItems:"center",gap:DS.sp.sm,
          padding:collapsed?"6px":"7px 10px",
          background:T.bg,border:`1px solid ${T.border}`,borderRadius:DS.r.md,
          color:T.text,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif",
        }}>
        {/* avatar user (chiquito) */}
        {user?.photoURL
          ? <img src={user.photoURL} alt="" style={{width:18,height:18,borderRadius:DS.r.full,flexShrink:0,border:`1px solid ${T.border}`}}/>
          : <span style={{width:18,height:18,borderRadius:DS.r.full,background:T.accentSolid+"33",color:T.accent,display:"flex",alignItems:"center",justifyContent:"center",fontWeight:DS.w.bold,fontSize:10,flexShrink:0}}>{userInitial}</span>
        }
        <OrgAvatar org={active} size={20}/>
        {!collapsed && (
          <>
            <span style={{flex:1,minWidth:0,fontSize:DS.font.md,fontWeight:DS.w.semibold,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",textAlign:"left"}}>{active.name}</span>
            <span style={{fontSize:DS.font.sm,color:T.textSm,flexShrink:0,marginLeft:2}}>▾</span>
          </>
        )}
      </button>
      {open && ReactDOM.createPortal(
        <div ref={dropRef} style={{position:"fixed",bottom:`calc(100vh - ${dropPos.top}px)`,left:dropPos.left,width:dropPos.width,background:T.card,border:`1px solid ${T.border}`,borderRadius:DS.r.lg,padding:DS.sp.xs,zIndex:9998,boxShadow:"0 10px 40px rgba(0,0,0,0.55)"}}>
          {/* Card de la org activa con Gestionar */}
          <div style={{display:"flex",alignItems:"center",gap:DS.sp.sm,padding:`${DS.sp.sm}px ${DS.sp.sm}px`,background:T.bg,borderRadius:DS.r.md,marginBottom:DS.sp.xs}}>
            <OrgAvatar org={active} size={34}/>
            <div style={{flex:1,minWidth:0}}>
              <div style={{fontSize:DS.font.lg,fontWeight:DS.w.bold,color:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{active.name}</div>
              <div style={{fontSize:DS.font.xs,color:T.textSm,marginTop:1}}>Admin</div>
            </div>
            <button onClick={()=>{ setOpen(false); onOpenManageOrg(active.id); }} title="Gestionar organización" style={{display:"flex",alignItems:"center",gap:5,background:"transparent",border:`1px solid ${T.border}`,borderRadius:DS.r.md,color:T.textMd,padding:"6px 10px",fontSize:DS.font.sm,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif"}}>
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 010 2.83 2 2 0 01-2.83 0l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-2 2 2 2 0 01-2-2v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83 0 2 2 0 010-2.83l.06-.06a1.65 1.65 0 00.33-1.82 1.65 1.65 0 00-1.51-1H3a2 2 0 01-2-2 2 2 0 012-2h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 010-2.83 2 2 0 012.83 0l.06.06a1.65 1.65 0 001.82.33H9a1.65 1.65 0 001-1.51V3a2 2 0 012-2 2 2 0 012 2v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 0 2 2 0 010 2.83l-.06.06a1.65 1.65 0 00-.33 1.82V9a1.65 1.65 0 001.51 1H21a2 2 0 012 2 2 2 0 01-2 2h-.09a1.65 1.65 0 00-1.51 1z"/></svg>
              Gestionar
            </button>
          </div>

          {/* Otras orgs — empty state estilo screenshot */}
          {others.length === 0 ? (
            <div style={{padding:"22px 14px",textAlign:"center",background:T.bg,borderRadius:DS.r.md,marginBottom:DS.sp.xs}}>
              <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round" style={{color:T.textSm,marginBottom:6,opacity:0.7}}>
                <path d="M3 21h18M5 21V7l8-4v18M19 21V11l-6-4"/><path d="M9 9v.01M9 12v.01M9 15v.01M9 18v.01"/>
              </svg>
              <div style={{fontSize:DS.font.sm,color:T.textSm}}>No hay otras organizaciones</div>
            </div>
          ) : (
            <div style={{marginBottom:DS.sp.xs}}>
              {others.map(org => (
                <button key={org.id}
                  onClick={()=>{ onSwitchOrg(org.id); setOpen(false); }}
                  style={{display:"flex",alignItems:"center",gap:DS.sp.sm,width:"100%",padding:"8px 10px",border:"none",background:"transparent",borderRadius:DS.r.md,cursor:"pointer",color:T.text,fontFamily:"'Inter',system-ui,sans-serif"}}
                  onMouseEnter={e=>{e.currentTarget.style.background=T.bg;}}
                  onMouseLeave={e=>{e.currentTarget.style.background="transparent";}}>
                  <OrgAvatar org={org} size={26}/>
                  <span style={{flex:1,minWidth:0,fontSize:DS.font.md,fontWeight:DS.w.medium,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap",textAlign:"left"}}>{org.name}</span>
                </button>
              ))}
            </div>
          )}

          {/* Crear organización */}
          <button
            onClick={()=>{ setOpen(false); onOpenCreateOrg(); }}
            disabled={!planAllowsMore}
            title={planAllowsMore?"Crear nueva organización":"Tu plan permite hasta 2 organizaciones. Pasate a Total para más."}
            style={{display:"flex",alignItems:"center",gap:DS.sp.sm,width:"100%",padding:"10px 12px",border:`1px solid ${T.border}`,background:planAllowsMore?T.bg:"transparent",borderRadius:DS.r.md,cursor:planAllowsMore?"pointer":"not-allowed",color:planAllowsMore?T.text:T.textSm,fontFamily:"'Inter',system-ui,sans-serif",opacity:planAllowsMore?1:0.65}}>
            <span style={{width:26,height:26,borderRadius:DS.r.md,background:planAllowsMore?T.accentSolid+"22":"transparent",border:planAllowsMore?"none":`1px dashed ${T.border}`,color:planAllowsMore?T.accent:T.textSm,display:"flex",alignItems:"center",justifyContent:"center",fontSize:18,fontWeight:DS.w.bold,flexShrink:0,lineHeight:1}}>+</span>
            <span style={{flex:1,fontSize:DS.font.md,fontWeight:DS.w.semibold,textAlign:"left"}}>Crear organización</span>
            {!planAllowsMore && <span style={{fontSize:9,padding:"2px 6px",borderRadius:4,background:T.accent+"22",color:T.accent,fontWeight:DS.w.bold,letterSpacing:0.3,textTransform:"uppercase"}}>Total</span>}
          </button>
        </div>,
        document.body
      )}
    </div>
  );
}

// ─── Modal "Crear organización" (F2) ───
function NewOrgModal({T, onClose, onCreate, existingCount, userPlan}) {
  const [name, setName] = React.useState("");
  const [color, setColor] = React.useState("#7c3aed");
  const [saving, setSaving] = React.useState(false);
  const COLORS = ["#7c3aed","#ec4899","#f97316","#eab308","#22c55e","#06b6d4","#3b82f6","#ef4444"];
  const overLimit = userPlan !== "total" && existingCount >= 2;

  async function handleSave() {
    if (!name.trim()) return;
    if (overLimit) return;
    setSaving(true);
    const ok = await onCreate({ name: name.trim(), color });
    setSaving(false);
    if (ok) onClose();
  }

  return ReactDOM.createPortal(
    <div style={{position:"fixed",inset:0,zIndex:9999,display:"flex",alignItems:"center",justifyContent:"center",background:"rgba(0,0,0,0.6)",backdropFilter:"blur(4px)",padding:16}} onClick={()=>!saving&&onClose()}>
      <div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:16,width:"100%",maxWidth:440,padding:"24px 26px"}} onClick={e=>e.stopPropagation()}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:16}}>
          <div>
            <div style={{fontSize:17,fontWeight:700,color:T.text}}>Nueva organización</div>
            <div style={{fontSize:11,color:T.textSm,marginTop:2}}>Vas a empezar de cero — vas a conectar TN/Shopify/ML/Meta y ARCA después.</div>
          </div>
          <button onClick={onClose} disabled={saving} style={{background:"transparent",border:"none",color:T.textMd,cursor:saving?"wait":"pointer",fontSize:18,padding:4}}>✕</button>
        </div>

        {overLimit ? (
          <div style={{padding:"18px 16px",background:T.yellowBg||T.bg,border:`1px solid ${T.yellow||T.border}55`,borderRadius:12,marginBottom:14}}>
            <div style={{fontSize:13,fontWeight:700,color:T.text,marginBottom:6}}>🔒 Llegaste al límite de tu plan</div>
            <div style={{fontSize:12,color:T.textMd,lineHeight:1.5}}>Tu plan permite hasta 2 organizaciones. Para tener más, pasate al plan <strong>Total</strong>.</div>
          </div>
        ) : (
          <>
            <label style={{display:"block",fontSize:12,fontWeight:600,color:T.textMd,marginBottom:5}}>Nombre</label>
            <input autoFocus value={name} onChange={e=>setName(e.target.value)} placeholder='Ej. "Inditropic" o "Soluna"'
              maxLength={40}
              style={{width:"100%",background:T.input,border:`1px solid ${T.inputBorder}`,borderRadius:10,padding:"10px 13px",fontSize:13,color:T.text,fontFamily:"'Inter',system-ui,sans-serif",boxSizing:"border-box",marginBottom:16}}/>

            <label style={{display:"block",fontSize:12,fontWeight:600,color:T.textMd,marginBottom:8}}>Color</label>
            <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:8}}>
              {COLORS.map(c => (
                <button key={c} onClick={()=>setColor(c)} title={c}
                  style={{width:32,height:32,borderRadius:8,background:c,border:color===c?`2px solid ${T.text}`:`2px solid transparent`,cursor:"pointer",padding:0,outline:"none"}}/>
              ))}
            </div>
          </>
        )}

        <div style={{display:"flex",gap:8,marginTop:18}}>
          <button onClick={onClose} disabled={saving} style={{flex:1,padding:"10px 14px",fontSize:13,fontWeight:600,border:`1px solid ${T.border}`,borderRadius:10,background:"transparent",color:T.textMd,cursor:saving?"wait":"pointer",fontFamily:"'Inter',system-ui,sans-serif"}}>Cancelar</button>
          {overLimit
            ? <button onClick={()=>{ window.location.hash="#/planes"; onClose(); }} style={{flex:1,padding:"10px 14px",fontSize:13,fontWeight:700,border:"none",borderRadius:10,background:T.accentSolid,color:"#fff",cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif"}}>Ver planes</button>
            : <button onClick={handleSave} disabled={saving||!name.trim()} style={{flex:1,padding:"10px 14px",fontSize:13,fontWeight:700,border:"none",borderRadius:10,background:T.accentSolid,color:"#fff",cursor:saving||!name.trim()?"not-allowed":"pointer",fontFamily:"'Inter',system-ui,sans-serif",opacity:saving||!name.trim()?0.6:1}}>{saving?"Creando...":"Crear y entrar"}</button>
          }
        </div>
      </div>
    </div>,
    document.body
  );
}

// ─── Modal "Gestionar organización" (F2) ───
function ManageOrgModal({T, org, totalOrgs, onClose, onSave, onDelete}) {
  const [name, setName] = React.useState(org.name||"");
  const [color, setColor] = React.useState(org.color||"#7c3aed");
  const [saving, setSaving] = React.useState(false);
  const [confirmDel, setConfirmDel] = React.useState(false);
  const COLORS = ["#7c3aed","#ec4899","#f97316","#eab308","#22c55e","#06b6d4","#3b82f6","#ef4444"];
  const canDelete = totalOrgs > 1; // no se puede borrar la única org

  async function handleSave() {
    if (!name.trim()) return;
    setSaving(true);
    const ok = await onSave({ ...org, name: name.trim(), color, updated_at: new Date().toISOString() });
    setSaving(false);
    if (ok) onClose();
  }
  async function handleDelete() {
    setSaving(true);
    const ok = await onDelete(org.id);
    setSaving(false);
    if (ok) onClose();
  }

  return ReactDOM.createPortal(
    <div style={{position:"fixed",inset:0,zIndex:9999,display:"flex",alignItems:"center",justifyContent:"center",background:"rgba(0,0,0,0.6)",backdropFilter:"blur(4px)",padding:16}} onClick={()=>!saving&&onClose()}>
      <div style={{background:T.card,border:`1px solid ${T.border}`,borderRadius:16,width:"100%",maxWidth:440,padding:"24px 26px"}} onClick={e=>e.stopPropagation()}>
        <div style={{display:"flex",alignItems:"center",justifyContent:"space-between",marginBottom:16}}>
          <div style={{fontSize:17,fontWeight:700,color:T.text}}>Gestionar organización</div>
          <button onClick={onClose} disabled={saving} style={{background:"transparent",border:"none",color:T.textMd,cursor:saving?"wait":"pointer",fontSize:18,padding:4}}>✕</button>
        </div>

        <label style={{display:"block",fontSize:12,fontWeight:600,color:T.textMd,marginBottom:5}}>Nombre</label>
        <input value={name} onChange={e=>setName(e.target.value)} maxLength={40}
          style={{width:"100%",background:T.input,border:`1px solid ${T.inputBorder}`,borderRadius:10,padding:"10px 13px",fontSize:13,color:T.text,fontFamily:"'Inter',system-ui,sans-serif",boxSizing:"border-box",marginBottom:16}}/>

        <label style={{display:"block",fontSize:12,fontWeight:600,color:T.textMd,marginBottom:8}}>Color</label>
        <div style={{display:"flex",gap:8,flexWrap:"wrap",marginBottom:16}}>
          {COLORS.map(c => (
            <button key={c} onClick={()=>setColor(c)} title={c}
              style={{width:32,height:32,borderRadius:8,background:c,border:color===c?`2px solid ${T.text}`:`2px solid transparent`,cursor:"pointer",padding:0}}/>
          ))}
        </div>

        {canDelete && (
          <div style={{borderTop:`1px solid ${T.border}`,paddingTop:14,marginTop:8}}>
            {!confirmDel ? (
              <button onClick={()=>setConfirmDel(true)} disabled={saving} style={{background:"transparent",border:`1px solid ${T.red}44`,color:T.red,borderRadius:10,padding:"8px 12px",fontSize:12,fontWeight:600,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif"}}>🗑 Borrar esta organización</button>
            ) : (
              <div style={{background:T.red+"10",border:`1px solid ${T.red}33`,borderRadius:10,padding:"12px 14px"}}>
                <div style={{fontSize:12,color:T.text,fontWeight:600,marginBottom:8}}>¿Borrar "{org.name}"? Se pierden las integraciones de esa org. Esta acción no se puede deshacer.</div>
                <div style={{display:"flex",gap:6}}>
                  <button onClick={()=>setConfirmDel(false)} disabled={saving} style={{flex:1,padding:"7px",fontSize:11,fontWeight:600,border:`1px solid ${T.border}`,borderRadius:8,background:"transparent",color:T.textMd,cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif"}}>Cancelar</button>
                  <button onClick={handleDelete} disabled={saving} style={{flex:1,padding:"7px",fontSize:11,fontWeight:700,border:"none",borderRadius:8,background:T.red,color:"#fff",cursor:"pointer",fontFamily:"'Inter',system-ui,sans-serif"}}>{saving?"Borrando...":"Sí, borrar"}</button>
                </div>
              </div>
            )}
          </div>
        )}

        <div style={{display:"flex",gap:8,marginTop:18}}>
          <button onClick={onClose} disabled={saving} style={{flex:1,padding:"10px 14px",fontSize:13,fontWeight:600,border:`1px solid ${T.border}`,borderRadius:10,background:"transparent",color:T.textMd,cursor:saving?"wait":"pointer",fontFamily:"'Inter',system-ui,sans-serif"}}>Cancelar</button>
          <button onClick={handleSave} disabled={saving||!name.trim()} style={{flex:1,padding:"10px 14px",fontSize:13,fontWeight:700,border:"none",borderRadius:10,background:T.accentSolid,color:"#fff",cursor:saving||!name.trim()?"not-allowed":"pointer",fontFamily:"'Inter',system-ui,sans-serif",opacity:saving||!name.trim()?0.6:1}}>{saving?"Guardando...":"Guardar"}</button>
        </div>
      </div>
    </div>,
    document.body
  );
}

// ── Logo Growith — usa los archivos PNG reales del brand ───────────────
// variant: "color" (púrpura), "blanco" (blanco), "negro" (negro), "trazo" (outline)
function GrowithLogo({size=28, variant="color", darkMode=false}) {
  // En dark mode usamos el logo blanco; en light mode el de color
  const src = variant === "auto"
    ? (darkMode ? "/logo-blanco.png" : "/logo-color.png")
    : `/logo-${variant}.png`;
  return (
    <img
      src={src}
      alt="Growith"
      width={size}
      height={size}
      style={{objectFit:"contain",flexShrink:0,display:"block"}}
    />
  );
}

function Sidebar({T, page, setPage, user, userPlan, isAdmin, adminOnlySections=[], onToggleDark, darkMode, onLogout, alerts={}, collapsed, setCollapsed, enviosTab, setEnviosTab, reclamosView, setReclamosView, metaTab, setMetaTab, stockTab, setStockTab, arcaTab, setArcaTab, tareasTab, setTareasTab, canjesTab, setCanjesTab, mlTab, setMlTab, connectedStores={}, orgs=[], activeOrgId=null, onSwitchOrg=()=>{}, onOpenCreateOrg=()=>{}, onOpenManageOrg=()=>{}}) {
  const GROUPS = [
    // Inicio queda suelto arriba de todo, sin etiqueta de grupo
    {id:"home",     label:"Inicio",    icon:"M3 12l9-9 9 9M5 10v10a2 2 0 002 2h3M19 10v10a2 2 0 01-2 2h-3M9 22V12h6v10"},
    { group:"ANALYTICS" },
    {id:"rendimiento", label:"Dashboard", icon:"M18 20V10M12 20V4M6 20v-6", adminOnly:true},
    {id:"meta",     label:"Meta Ads",  icon:"M18 2h-3a5 5 0 00-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 011-1h3z", integrationKey:"meta",
      subs:[{id:"productos",label:"Productos"},{id:"analisis",label:"Análisis"},{id:"biblioteca",label:"Biblioteca"},{id:"reglas",label:"Reglas"},{id:"creativos",label:"Publicar"},{id:"cuenta",label:"Cuenta"}]},
    {id:"stock",    label:"Stock",     icon:"M21 16V8a2 2 0 00-1-1.73l-7-4a2 2 0 00-2 0l-7 4A2 2 0 003 8v8a2 2 0 001 1.73l7 4a2 2 0 002 0l7-4A2 2 0 0021 16zM3.27 6.96L12 12.01l8.73-5.05M12 22.08V12", count:alerts.stock, badge:"red",
      subs:[{id:"analisis",label:"Análisis"},{id:"productos",label:"Productos"},{id:"facturacion",label:"Facturación"},{id:"items",label:"Items"},{id:"depositos",label:"Depósitos"},{id:"historial",label:"Historial"},{id:"alertas",label:"Alertas"}]},
    {id:"ml",       label:"Mercado Libre", icon:"M12 22a10 10 0 100-20 10 10 0 000 20zM8 14s1.5 2 4 2 4-2 4-2M9 9h.01M15 9h.01", integrationKey:"ml",
      subs:[{id:"gestion",label:"Gestión"},{id:"analytics",label:"Analytics"}]},
    { group:"OPERACIONES" },
    {id:"envios",   label:"Envíos",    icon:"M16 16h6m-3-3v6M1 3h15v13H1zM16 8h4l3 3v5h-7V8zM5.5 21a2.5 2.5 0 100-5 2.5 2.5 0 000 5zM18.5 21a2.5 2.5 0 100-5 2.5 2.5 0 000 5z", count:alerts.envios,
      subs:[{id:"panel",label:"Panel de Envíos"},{id:"sku",label:"SKU en Rótulos"},{id:"seguimientos",label:"Seguimientos"}]},
    {id:"reclamos", label:"Reclamos",  icon:"M21 11.5a8.38 8.38 0 01-.9 3.8 8.5 8.5 0 01-7.6 4.7 8.38 8.38 0 01-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 01-.9-3.8 8.5 8.5 0 014.7-7.6 8.38 8.38 0 013.8-.9h.5a8.48 8.48 0 018 8v.5z", count:alerts.reclamos, badge:"red",
      subs:[{id:"reclamos",label:"Reclamos"},{id:"historial",label:"Historial"}]},
    {id:"canjes",   label:"Canjes",    icon:"M16 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2M23 21v-2a4 4 0 00-3-3.87M16 3.13a4 4 0 010 7.75M12.5 7a4 4 0 11-8 0 4 4 0 018 0z", count:alerts.canjes, badge:"orange",
      subs:[{id:"activos",label:"Activos"},{id:"historial",label:"Historial"},{id:"influencers",label:"Influencers"}]},
    {id:"tareas",   label:"Tareas",    icon:"M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2m-6 9l2 2 4-4", count:alerts.tareas, badge:"orange",
      subs:[{id:"tareas",label:"Tareas"},{id:"equipo",label:"Equipo"},{id:"creativos",label:"Creativos"}]},
    { group:"FINANZAS" },
    {id:"arca",     label:"Facturador", icon:"M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8zM14 2v6h6M16 13H8M16 17H8M10 9H8",
      subs:[{id:"metricas",label:"Métricas"},{id:"pendientes",label:"Pendientes"},{id:"manual",label:"Factura manual"},{id:"historico",label:"Registros"},{id:"cuits",label:"CUITs"}]},
  ];
  const initial = (user?.displayName||user?.email||"?").charAt(0).toUpperCase();
  const W = collapsed ? 64 : 224;

  const NavBtn = ({item}) => {
    const active = page === item.id;
    const badgeColor = item.badge==="red" ? T.red : item.badge==="orange" ? T.orange : T.accent;
    const isConnected = item.integrationKey ? connectedStores[item.integrationKey] : undefined;
    return (
      <button onClick={()=>setPage(item.id)} title={collapsed?item.label:undefined}
        style={{display:"flex",alignItems:"center",gap:9,padding:collapsed?"10px 0":"8px 10px",
          background:active?T.accentSolid+"20":"transparent",border:"none",
          borderRadius:DS.r.md,cursor:"pointer",textAlign:"left",
          color:active?T.accent:T.textMd,fontWeight:active?DS.w.semibold:DS.w.medium,
          fontSize:DS.font.sm,fontFamily:"'Inter',system-ui,sans-serif",
          transition:`all 0.12s ${DS.ease}`,justifyContent:collapsed?"center":"flex-start",
          position:"relative",width:"100%",letterSpacing:active?0:-0.1}}
        onMouseEnter={e=>{if(!active)e.currentTarget.style.background=T.card;}}
        onMouseLeave={e=>{if(!active)e.currentTarget.style.background="transparent";}}>
        {item.id==="ml"
          ? <svg width="20" height="20" viewBox="0 0 48 48" fill="none" stroke="currentColor" strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" style={{flexShrink:0,opacity:active?1:0.65}}><ellipse cx="24" cy="24" rx="19.5" ry="12.978"/><path d="M9.7044,15.5305A20.8345,20.8345,0,0,0,16.09,17.3957a22.8207,22.8207,0,0,0,4.546-.7731"/><path d="M38.8824,15.6143a8.6157,8.6157,0,0,1-5.1653,1.4849c-3.3351,0-6.2255-2.1987-9.2148-2.1987-2.6681,0-7.189,4.3727-7.189,5.1633s1.3094,1.26,2.3717.7411c.6215-.3036,3.31-2.9151,5.4843-2.9151s9.2186,7.1361,9.8571,7.8066c.9882,1.0376-.9264,3.2733-2.1493,2.05s-3.4092-3.1621-3.4092-3.1621"/><path d="M43.4,22.6826a23.9981,23.9981,0,0,0-8.5467,2.6926"/><path d="M32.5807,27.4555c.9881,1.0376-.9265,3.2733-2.1493,2.05S27.85,26.9933,27.85,26.9933"/><path d="M30.1349,29.2147c.9882,1.0376-.9264,3.2733-2.1493,2.05S25.96,29.3032,25.96,29.3032"/><path d="M24.2015,31.3156A2.309,2.309,0,0,0,27.85,31.13"/><path d="M24.2015,31.3156c.5306-.6964.49-3.1817-2.2437-2.6876.6423-1.2188.0658-3.1457-2.3881-2.0093A1.69,1.69,0,0,0,16.424,25.96a1.4545,1.4545,0,0,0-2.8-.28c-.5435,1.1035.2964,3.0963,2.0916,1.9763-.1812,1.9435.84,2.5364,2.6845,1.7788.0989,1.91,1.367,1.7457,2.2728,1.3011A1.9376,1.9376,0,0,0,24.2015,31.3156Z"/><path d="M4.6706,22.2785a18.3081,18.3081,0,0,1,9.0635,3.2144"/></svg>
          : <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={active?"2.2":"1.8"} strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0,opacity:active?1:0.65}}><path d={item.icon}/></svg>
        }
        {!collapsed&&<span style={{flex:1}}>{item.label}</span>}
        {!collapsed&&item.count>0&&<span style={{fontSize:10,fontWeight:DS.w.bold,padding:"1px 6px",borderRadius:DS.r.full,background:badgeColor+(active?"33":"22"),color:badgeColor,lineHeight:1.5,minWidth:18,textAlign:"center"}}>{item.count>99?"99+":item.count}</span>}
        {!collapsed&&isConnected!==undefined&&<span style={{width:7,height:7,borderRadius:"50%",background:isConnected?T.green:T.textSm,flexShrink:0,opacity:0.8}} title={isConnected?"Conectado":"Sin conectar"}/>}
        {collapsed&&item.count>0&&<span style={{position:"absolute",top:6,right:8,width:6,height:6,borderRadius:DS.r.full,background:badgeColor}}/>}
        {collapsed&&isConnected!==undefined&&!item.count&&<span style={{position:"absolute",top:6,right:8,width:6,height:6,borderRadius:DS.r.full,background:isConnected?T.green:T.textSm}}/>}
      </button>
    );
  };

  return (
    <div style={{width:W,minWidth:W,height:"100vh",background:T.surface,borderRight:`1px solid ${T.border}`,
      display:"flex",flexDirection:"column",position:"sticky",top:0,
      transition:`width 0.22s ${DS.ease}, min-width 0.22s ${DS.ease}`,overflow:"hidden",zIndex:50,
    }} className="hide-mobile">
      {/* Logo */}
      {collapsed ? (
        <div style={{display:"flex",flexDirection:"column",alignItems:"center",justifyContent:"center",gap:6,borderBottom:`1px solid ${T.border}`,height:60,padding:"0 4px"}}>
          <GrowithLogo size={22} variant="color"/>
          <button onClick={()=>setCollapsed(false)} title="Expandir" style={{background:"transparent",border:`1px solid ${T.border}`,borderRadius:DS.r.sm,color:T.textSm,cursor:"pointer",padding:"2px 6px",display:"flex",alignItems:"center",justifyContent:"center",transition:`all 0.15s ${DS.ease}`,width:36}}
            onMouseEnter={e=>{e.currentTarget.style.background=T.card;e.currentTarget.style.color=T.text;}}
            onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.color=T.textSm;}}>
            <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M9 18l6-6-6-6"/></svg>
          </button>
        </div>
      ) : (
        <div style={{padding:DS.sp.lg,display:"flex",alignItems:"center",gap:10,borderBottom:`1px solid ${T.border}`,height:60}}>
          <div style={{flexShrink:0,display:"flex",alignItems:"center",justifyContent:"center"}}>
            <GrowithLogo size={24} variant="color"/>
          </div>
          <span style={{fontWeight:DS.w.bold,fontSize:DS.font.xl,color:T.text,letterSpacing:-0.3}}>Growith</span>
          <button onClick={()=>setCollapsed(true)} title="Colapsar" style={{marginLeft:"auto",background:"transparent",border:`1px solid ${T.border}`,borderRadius:DS.r.sm,color:T.textSm,cursor:"pointer",padding:"3px 5px",display:"flex",alignItems:"center",justifyContent:"center",transition:`all 0.15s ${DS.ease}`}}
            onMouseEnter={e=>{e.currentTarget.style.background=T.card;e.currentTarget.style.color=T.text;}}
            onMouseLeave={e=>{e.currentTarget.style.background="transparent";e.currentTarget.style.color=T.textSm;}}>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M15 18l-6-6 6-6"/></svg>
          </button>
        </div>
      )}

      {/* Nav */}
      <nav style={{flex:1,padding:DS.sp.sm,display:"flex",flexDirection:"column",gap:2,overflowY:"auto"}}>
        {GROUPS.filter(item=>!(adminOnlySections||[]).includes(item.id)||isAdmin).map((item,i)=>{
          if(item.group) {
            if(collapsed) return null;
            return (
              <div key={item.group+i} style={{padding:"10px 12px 3px",fontSize:DS.font.xs,fontWeight:DS.w.bold,color:T.textSm,letterSpacing:0.7,textTransform:"uppercase",opacity:0.55,userSelect:"none"}}>
                {item.group}
              </div>
            );
          }
          const active = page===item.id;
          // Subs solo cuando estás dentro del módulo (revertido del bloque
          // siempre-desplegado de Escalafy — el usuario prefiere la fluidez
          // del despliegue al click). Se ocultan otra vez al cambiar de módulo.
          const showSubs = active && item.subs && !collapsed;
          return (
            <React.Fragment key={item.id}>
              <NavBtn item={item}/>
              {showSubs && (
                <div style={{
                  marginLeft:22,
                  paddingLeft:14,
                  borderLeft:`1.5px solid ${T.border}`,
                  marginTop:2,
                  marginBottom:4,
                  display:"flex",
                  flexDirection:"column",
                  gap:1,
                }}>
                  {item.subs.map(sub=>{
                    // subActive solo cuando el módulo padre es el activo —
                    // antes daba highlight aún navegando otra sección, ahora
                    // que las subs son visibles siempre eso confundía.
                    const subActive = active && ((item.id==="envios"&&enviosTab===sub.id)||(item.id==="reclamos"&&reclamosView===sub.id)||(item.id==="meta"&&metaTab===sub.id)||(item.id==="stock"&&stockTab===sub.id)||(item.id==="arca"&&arcaTab===sub.id)||(item.id==="tareas"&&tareasTab===sub.id)||(item.id==="canjes"&&canjesTab===sub.id)||(item.id==="ml"&&mlTab===sub.id));
                    return (
                      <button key={sub.id}
                        onClick={()=>{
                          setPage(item.id);
                          if(item.id==="envios") setEnviosTab&&setEnviosTab(sub.id);
                          if(item.id==="reclamos") setReclamosView&&setReclamosView(sub.id);
                          if(item.id==="meta") setMetaTab&&setMetaTab(sub.id);
                          if(item.id==="stock") setStockTab&&setStockTab(sub.id);
                          if(item.id==="arca") setArcaTab&&setArcaTab(sub.id);
                          if(item.id==="tareas") setTareasTab&&setTareasTab(sub.id);
                          if(item.id==="canjes") setCanjesTab&&setCanjesTab(sub.id);
                          if(item.id==="ml") setMlTab&&setMlTab(sub.id);
                        }}
                        style={{display:"flex",alignItems:"center",gap:8,padding:"5px 8px",
                          background:"none",border:"none",
                          borderRadius:DS.r.sm,cursor:"pointer",textAlign:"left",width:"100%",
                          color:subActive?T.accent:T.textSm,
                          fontWeight:subActive?DS.w.semibold:DS.w.regular,
                          fontSize:DS.font.sm,fontFamily:"'Inter',system-ui,sans-serif",
                          transition:`color 0.12s ${DS.ease}`,letterSpacing:subActive?0:-0.1}}
                        onMouseEnter={e=>{if(!subActive)e.currentTarget.style.color=T.textMd;}}
                        onMouseLeave={e=>{if(!subActive)e.currentTarget.style.color=T.textSm;}}>
                        <span style={{
                          width:subActive?14:6, height:1.5,
                          background:subActive?T.accentSolid:T.textSm+"55",
                          borderRadius:2, flexShrink:0,
                          transition:`width 0.18s ${DS.ease}, background 0.18s`,
                        }}/>
                        {sub.label}
                      </button>
                    );
                  })}
                </div>
              )}
            </React.Fragment>
          );
        })}
      </nav>

      {/* Org Switcher (multi-org F1) — encima del User Section */}
      <OrgSwitcher T={T} user={user} userPlan={userPlan} orgs={orgs} activeOrgId={activeOrgId} onSwitchOrg={onSwitchOrg} onOpenCreateOrg={onOpenCreateOrg} onOpenManageOrg={onOpenManageOrg} collapsed={collapsed}/>

      {/* User Section */}
      <div style={{borderTop:`1px solid ${T.border}`,padding:DS.sp.sm,marginTop:DS.sp.sm}}>
        {!collapsed&&(
          <div style={{display:"flex",alignItems:"center",gap:DS.sp.md,padding:DS.sp.sm,marginBottom:DS.sp.xs}}>
            {user?.photoURL
              ?<img src={user.photoURL} alt="" style={{width:28,height:28,borderRadius:DS.r.full,border:`1px solid ${T.border}`,flexShrink:0}}/>
              :<div style={{width:28,height:28,borderRadius:DS.r.full,background:T.accentSolid+"33",color:T.accent,display:"flex",alignItems:"center",justifyContent:"center",fontWeight:DS.w.bold,fontSize:DS.font.md,flexShrink:0}}>{initial}</div>
            }
            <div style={{flex:1,minWidth:0}}>
              <div style={{fontSize:DS.font.md,fontWeight:DS.w.semibold,color:T.text,overflow:"hidden",textOverflow:"ellipsis",whiteSpace:"nowrap"}}>{user?.displayName||user?.email?.split("@")[0]}</div>
              <div style={{fontSize:DS.font.xs,color:T.textSm}}>{userPlan==="free"?"Plan Free":userPlan==="starter"?"Starter":userPlan==="pro"?"Pro":"Total"}</div>
            </div>
          </div>
        )}
        <div style={{display:"flex",flexDirection:collapsed?"column":"row",gap:4}}>
          <button onClick={()=>setPage("config")} title="Configuración" style={{flex:1,background:"transparent",border:`1px solid ${T.border}`,borderRadius:DS.r.md,color:T.textMd,cursor:"pointer",padding:"6px",fontSize:DS.font.sm,display:"flex",alignItems:"center",justifyContent:"center",gap:5}}>
            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 010 2.83 2 2 0 01-2.83 0l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-2 2 2 2 0 01-2-2v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83 0 2 2 0 010-2.83l.06-.06a1.65 1.65 0 00.33-1.82 1.65 1.65 0 00-1.51-1H3a2 2 0 01-2-2 2 2 0 012-2h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 010-2.83 2 2 0 012.83 0l.06.06a1.65 1.65 0 001.82.33H9a1.65 1.65 0 001-1.51V3a2 2 0 012-2 2 2 0 012 2v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 0 2 2 0 010 2.83l-.06.06a1.65 1.65 0 00-.33 1.82V9a1.65 1.65 0 001.51 1H21a2 2 0 012 2 2 2 0 01-2 2h-.09a1.65 1.65 0 00-1.51 1z"/></svg>
            {!collapsed&&"Config"}
          </button>
          <button onClick={onToggleDark} title={darkMode?"Modo claro":"Modo oscuro"} style={{background:"transparent",border:`1px solid ${T.border}`,borderRadius:DS.r.md,color:T.textMd,cursor:"pointer",padding:"6px 8px",display:"flex",alignItems:"center",justifyContent:"center"}}>
            {darkMode
              ?<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg>
              :<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M21 12.79A9 9 0 1111.21 3 7 7 0 0021 12.79z"/></svg>
            }
          </button>
          {isAdmin&&(
            <button onClick={()=>setPage("admin")} title="Admin" style={{background:"transparent",border:`1px solid ${T.yellow}44`,borderRadius:DS.r.md,color:T.yellow,cursor:"pointer",padding:"6px 9px",fontSize:DS.font.sm}}>👑</button>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── Command Palette (Ctrl+K) ───
function CommandPalette({T, open, onClose, setPage, isAdmin}) {
  const [q, setQ] = React.useState("");
  const [selIdx, setSelIdx] = React.useState(0);
  const inputRef = React.useRef(null);
  React.useEffect(()=>{
    if(open){ inputRef.current?.focus(); setSelIdx(0); }
    else setQ("");
  },[open]);
  React.useEffect(()=>{ setSelIdx(0); },[q]);
  React.useEffect(()=>{
    if(!open) return;
    const onKey = (e)=>{
      if(e.key==="Escape"){ onClose(); return; }
      if(e.key==="ArrowDown"){ e.preventDefault(); setSelIdx(i=>Math.min(i+1, filtered.length-1)); }
      if(e.key==="ArrowUp"){ e.preventDefault(); setSelIdx(i=>Math.max(i-1,0)); }
      if(e.key==="Enter"&&filtered[selIdx]){ setPage(filtered[selIdx].page); onClose(); }
    };
    window.addEventListener("keydown", onKey);
    return ()=>window.removeEventListener("keydown", onKey);
  },[open, onClose, selIdx, q]);

  const items = [
    {label:"Inicio",              page:"home",     icon:"M3 12l9-9 9 9M5 10v10a2 2 0 002 2h3M19 10v10a2 2 0 01-2 2h-3M9 22V12h6v10"},
    {label:"Envíos",              page:"envios",   icon:"M16 16h6m-3-3v6M1 3h15v13H1zM16 8h4l3 3v5h-7V8zM5.5 21a2.5 2.5 0 100-5 2.5 2.5 0 000 5zM18.5 21a2.5 2.5 0 100-5 2.5 2.5 0 000 5z"},
    {label:"Reclamos",            page:"reclamos", icon:"M21 11.5a8.38 8.38 0 01-.9 3.8 8.5 8.5 0 01-7.6 4.7 8.38 8.38 0 01-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 01-.9-3.8 8.5 8.5 0 014.7-7.6 8.38 8.38 0 013.8-.9h.5a8.48 8.48 0 018 8v.5z"},
    {label:"Canjes",              page:"canjes",   icon:"M16 21v-2a4 4 0 00-4-4H5a4 4 0 00-4 4v2M23 21v-2a4 4 0 00-3-3.87M16 3.13a4 4 0 010 7.75M12.5 7a4 4 0 11-8 0 4 4 0 018 0z"},
    {label:"Stock & Estadísticas", page:"stock",   icon:"M21 16V8a2 2 0 00-1-1.73l-7-4a2 2 0 00-2 0l-7 4A2 2 0 003 8v8a2 2 0 001 1.73l7 4a2 2 0 002 0l7-4A2 2 0 0021 16zM3.27 6.96L12 12.01l8.73-5.05M12 22.08V12"},
    {label:"Gestión Mercado Libre", page:"ml",     icon:"M12 22a10 10 0 100-20 10 10 0 000 20zM8 14s1.5 2 4 2 4-2 4-2M9 9h.01M15 9h.01"},
    {label:"Meta Ads",            page:"meta",     icon:"M18 2h-3a5 5 0 00-5 5v3H7v4h3v8h4v-8h3l1-4h-4V7a1 1 0 011-1h3z"},
    {label:"Facturador",          page:"arca",     icon:"M14 2H6a2 2 0 00-2 2v16a2 2 0 002 2h12a2 2 0 002-2V8zM14 2v6h6M16 13H8M16 17H8M10 9H8"},
    {label:"Configuración",        page:"config",   icon:"M12 15a3 3 0 100-6 3 3 0 000 6zM19.4 15a1.65 1.65 0 00.33 1.82l.06.06a2 2 0 010 2.83 2 2 0 01-2.83 0l-.06-.06a1.65 1.65 0 00-1.82-.33 1.65 1.65 0 00-1 1.51V21a2 2 0 01-4 0v-.09A1.65 1.65 0 009 19.4a1.65 1.65 0 00-1.82.33l-.06.06a2 2 0 01-2.83 0 2 2 0 010-2.83l.06-.06A1.65 1.65 0 004.68 15a1.65 1.65 0 00-1.51-1H3a2 2 0 010-4h.09A1.65 1.65 0 004.6 9a1.65 1.65 0 00-.33-1.82l-.06-.06a2 2 0 010-2.83 2 2 0 012.83 0l.06.06A1.65 1.65 0 009 4.68a1.65 1.65 0 001-1.51V3a2 2 0 014 0v.09a1.65 1.65 0 001 1.51 1.65 1.65 0 001.82-.33l.06-.06a2 2 0 012.83 0 2 2 0 010 2.83l-.06.06A1.65 1.65 0 0019.4 9a1.65 1.65 0 001.51 1H21a2 2 0 010 4h-.09a1.65 1.65 0 00-1.51 1z"},
    {label:"Planes",              page:"planes",   icon:"M12 2l3.09 6.26L22 9.27l-5 4.87 1.18 6.88L12 17.77l-6.18 3.25L7 14.14 2 9.27l6.91-1.01L12 2z"},
    ...(isAdmin?[
      {label:"Admin Panel",  page:"admin",       icon:"M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"},
      {label:"Dashboard",     page:"rendimiento", icon:"M18 20V10M12 20V4M6 20v-6"},
    ]:[]),
  ];
  const filtered = items.filter(i => !q || i.label.toLowerCase().includes(q.toLowerCase()));

  if(!open) return null;
  return ReactDOM.createPortal(
    <div onClick={onClose}
      style={{position:"fixed", inset:0, zIndex:10000, background:"rgba(0,0,0,0.5)", backdropFilter:"blur(6px)", display:"flex", alignItems:"flex-start", justifyContent:"center", paddingTop:"15vh"}}>
      <div onClick={e=>e.stopPropagation()}
        style={{background:T.card, border:`1px solid ${T.border}`, borderRadius:DS.r["2xl"], width:"100%", maxWidth:560, boxShadow:DS.shadow.xl, overflow:"hidden"}}>
        <div style={{display:"flex", alignItems:"center", gap:10, padding:"14px 18px", borderBottom:`1px solid ${T.border}`}}>
          <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke={T.textSm} strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="11" cy="11" r="8"/><path d="M21 21l-4.35-4.35"/></svg>
          <input ref={inputRef} type="text" placeholder="Buscar sección, acción..." value={q} onChange={e=>setQ(e.target.value)}
            style={{flex:1, border:"none", background:"transparent", color:T.text, fontSize:DS.font.lg, outline:"none", fontFamily:"'Inter',system-ui,sans-serif"}}/>
          <span style={{fontSize:DS.font.xs, color:T.textSm, padding:"2px 6px", border:`1px solid ${T.border}`, borderRadius:DS.r.sm}}>ESC</span>
        </div>
        <div style={{maxHeight:380, overflowY:"auto", padding:DS.sp.sm}}>
          {filtered.length===0 ? (
            <div style={{padding:"32px 16px", textAlign:"center", color:T.textSm, fontSize:DS.font.md}}>Sin resultados</div>
          ) : filtered.map((item,i)=>(
            <button key={i} onClick={()=>{setPage(item.page);onClose();}}
              onMouseEnter={()=>setSelIdx(i)}
              style={{display:"flex", alignItems:"center", gap:DS.sp.md, padding:"10px 12px", width:"100%", border:"none", background:selIdx===i?T.surface:"transparent", borderRadius:DS.r.md, cursor:"pointer", textAlign:"left", color:T.text, fontSize:DS.font.base, transition:`background 0.1s`}}>
              {item.page==="ml"
                ? <svg width="20" height="20" viewBox="0 0 48 48" fill="none" stroke={T.accent} strokeLinecap="round" strokeLinejoin="round" strokeWidth="2.5" style={{flexShrink:0,opacity:0.85}}><ellipse cx="24" cy="24" rx="19.5" ry="12.978"/><path d="M9.7044,15.5305A20.8345,20.8345,0,0,0,16.09,17.3957a22.8207,22.8207,0,0,0,4.546-.7731"/><path d="M38.8824,15.6143a8.6157,8.6157,0,0,1-5.1653,1.4849c-3.3351,0-6.2255-2.1987-9.2148-2.1987-2.6681,0-7.189,4.3727-7.189,5.1633s1.3094,1.26,2.3717.7411c.6215-.3036,3.31-2.9151,5.4843-2.9151s9.2186,7.1361,9.8571,7.8066c.9882,1.0376-.9264,3.2733-2.1493,2.05s-3.4092-3.1621-3.4092-3.1621"/><path d="M43.4,22.6826a23.9981,23.9981,0,0,0-8.5467,2.6926"/><path d="M32.5807,27.4555c.9881,1.0376-.9265,3.2733-2.1493,2.05S27.85,26.9933,27.85,26.9933"/><path d="M30.1349,29.2147c.9882,1.0376-.9264,3.2733-2.1493,2.05S25.96,29.3032,25.96,29.3032"/><path d="M24.2015,31.3156A2.309,2.309,0,0,0,27.85,31.13"/><path d="M24.2015,31.3156c.5306-.6964.49-3.1817-2.2437-2.6876.6423-1.2188.0658-3.1457-2.3881-2.0093A1.69,1.69,0,0,0,16.424,25.96a1.4545,1.4545,0,0,0-2.8-.28c-.5435,1.1035.2964,3.0963,2.0916,1.9763-.1812,1.9435.84,2.5364,2.6845,1.7788.0989,1.91,1.367,1.7457,2.2728,1.3011A1.9376,1.9376,0,0,0,24.2015,31.3156Z"/><path d="M4.6706,22.2785a18.3081,18.3081,0,0,1,9.0635,3.2144"/></svg>
                : <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke={T.accent} strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" style={{flexShrink:0,opacity:0.85}}><path d={item.icon}/></svg>
              }
              <span style={{flex:1, fontWeight:DS.w.medium}}>{item.label}</span>
              <span style={{fontSize:DS.font.xs, color:T.textSm}}>↵</span>
            </button>
          ))}
        </div>
        <div style={{padding:"8px 16px", borderTop:`1px solid ${T.border}`, fontSize:DS.font.xs, color:T.textSm, display:"flex", justifyContent:"space-between"}}>
          <span>↑↓ navegar · ↵ seleccionar</span>
          <span>⌘K / Ctrl+K</span>
        </div>
      </div>
    </div>,
    document.body
  );
}

// ─── Onboarding Wizard ───
function OnboardingWizard({T, user, onComplete}) {
  const [step, setStep] = React.useState(1);
  const totalSteps = 3;

  const steps = [
    {
      n:1,
      icon:"🛍",
      title:"Conectá tu tienda online",
      desc:"Vincula Tienda Nube o Shopify para sincronizar pedidos, productos y stock automáticamente.",
      actions: (
        <div style={{display:"flex",flexDirection:"column",gap:DS.sp.md}}>
          <Btn T={T} variant="primary" size="lg" onClick={()=>{
            const clientId="30036";
            const redirectUri=encodeURIComponent(`${window.location.origin}/api/tn-callback`);
            const state=encodeURIComponent(user?.uid||"");
            window.location.href=`https://www.tiendanube.com/apps/${clientId}/authorize?state=${state}&redirect_uri=${redirectUri}`;
          }}>
            🛒 Conectar Tienda Nube
          </Btn>
          <Btn T={T} variant="secondary" size="lg" onClick={()=>onComplete("shopify")}>
            🛍 Conectar Shopify
          </Btn>
        </div>
      ),
    },
    {
      n:2,
      icon:"📣",
      title:"Conectá Meta Ads",
      desc:"Opcional. Conecta Facebook/Instagram Ads para ver el rendimiento de tus campañas y calcular ROAS real.",
      actions: (
        <div style={{display:"flex",gap:DS.sp.md}}>
          <Btn T={T} variant="primary" size="lg" style={{flex:1}} onClick={()=>setStep(3)}>Configurar después</Btn>
          <Btn T={T} variant="secondary" size="lg" style={{flex:1}} onClick={()=>setStep(3)}>Más tarde</Btn>
        </div>
      ),
    },
    {
      n:3,
      icon:"📄",
      title:"Facturación electrónica (ARCA)",
      desc:"Opcional. Configurá tu CUIT y certificado ARCA para emitir facturas automáticas. Podés saltearlo y configurarlo después.",
      actions: (
        <div style={{display:"flex",gap:DS.sp.md}}>
          <Btn T={T} variant="primary" size="lg" style={{flex:1}} onClick={()=>onComplete("done")}>✓ Comenzar a usar Growith</Btn>
        </div>
      ),
    },
  ];
  const current = steps[step-1];

  return (
    <div style={{position:"fixed",inset:0,background:T.bg,zIndex:9999,display:"flex",alignItems:"center",justifyContent:"center",padding:DS.sp.lg}}>
      <div style={{background:T.card, border:`1px solid ${T.border}`, borderRadius:DS.r["2xl"], padding:"40px 36px", maxWidth:520, width:"100%", boxShadow:DS.shadow.xl}}>
        {/* Progress */}
        <div style={{display:"flex",gap:6,marginBottom:DS.sp["3xl"]}}>
          {[1,2,3].map(n=>(
            <div key={n} style={{flex:1, height:4, borderRadius:DS.r.sm, background: n<=step ? T.accentSolid : T.borderL, transition:"background 0.3s"}}/>
          ))}
        </div>
        <div style={{textAlign:"center", marginBottom:DS.sp["2xl"]}}>
          <div style={{fontSize:48, marginBottom:DS.sp.md}}>{current.icon}</div>
          <div style={{fontSize:DS.font["2xl"], fontWeight:DS.w.bold, color:T.text, marginBottom:DS.sp.sm, letterSpacing:-0.5}}>{current.title}</div>
          <div style={{fontSize:DS.font.lg, color:T.textMd, lineHeight:1.5}}>{current.desc}</div>
        </div>
        {current.actions}
        <div style={{textAlign:"center", marginTop:DS.sp.lg}}>
          <button onClick={()=>onComplete("skip")} style={{background:"transparent",border:"none",color:T.textSm,cursor:"pointer",fontSize:DS.font.sm,padding:DS.sp.sm,fontFamily:"'Inter',system-ui,sans-serif"}}>
            Saltar onboarding por ahora
          </button>
        </div>
        <div style={{textAlign:"center",fontSize:DS.font.xs,color:T.textSm,marginTop:DS.sp.md}}>Paso {step} de {totalSteps}</div>
      </div>
    </div>
  );
}

function DSBadge({T, color, children, size="md"}) {
  const c = color||T.accent;
  return (
    <span style={{
      fontSize: size==="sm"?DS.font.xs:DS.font.sm,
      padding: size==="sm"?"2px 7px":"3px 9px",
      borderRadius: DS.r.sm,
      background: c+"20",
      color: c,
      fontWeight: DS.w.bold,
      border: `1px solid ${c}33`,
      display: "inline-flex", alignItems:"center", gap:4,
      lineHeight: 1.4,
      whiteSpace: "nowrap",
    }}>
      {children}
    </span>
  );
}

