                    <div>
                      <div style={{fontSize:11,fontWeight:600,color:T.textSm,marginBottom:4}}>CPA ($)</div>
                      <input type="number" step="0.01" value={cCpa} onChange={e=>setCCpa(e.target.value)} placeholder="Ej: 850" style={{...iS,fontSize:13,width:"100%"}}/>
                    </div>
